query:
mutation Rename($p0: ProductUpdateInput!, $p1: ProductUpdateInput!, $p2: ProductUpdateInput!, $p3: ProductUpdateInput!, $p4: ProductUpdateInput!, $p5: ProductUpdateInput!, $p6: ProductUpdateInput!) {
  a0: productUpdate(product: $p0) { product { id handle } userErrors { field message } }
  a1: productUpdate(product: $p1) { product { id handle } userErrors { field message } }
  a2: productUpdate(product: $p2) { product { id handle } userErrors { field message } }
  a3: productUpdate(product: $p3) { product { id handle } userErrors { field message } }
  a4: productUpdate(product: $p4) { product { id handle } userErrors { field message } }
  a5: productUpdate(product: $p5) { product { id handle } userErrors { field message } }
  a6: productUpdate(product: $p6) { product { id handle } userErrors { field message } }
}
